      "a": "黄遵宪《日本杂事诗》以竹枝词的形式写新事物而毫无滞碍，能够“熔铸新理想以入旧风格”，是新派诗的代表，这首七绝是《日本杂事诗》中的一首，写的是日本最高的山峰富士山。（2分）为了突出它的高峻，诗人连用“拔地”“摩天”“独立”三个词语，渲染出富士山伟岸巍峨、令人“高山仰止”的气势。（2分）又借美称“莲峰”赞美它仿佛是从东洋海面上长出来的一朵新荷，标明了“莲峰”的方位，用“清”字赋予“莲峰”以助势，以动写静，更显得富士山卓然兀立、高标独秀。（2分）诗人又连用两个夸张，从时间上讴歌积雪的亘古不化（“二千五百年前雪”），从空间上赞颂积雪的广大无垠（“一白茫茫”），揭示出富士山不仅高大、美好，而且纯洁、永恒。（2分）高是体，美是形，纯洁永恒才是富士山的神，突出日本人对视为圣山的富士山的景仰。（1分）（言之成理，即可给分）",
