   "essay": {
    "head": "四、赏析题与论述题",
    "desc": "赏析题9分、论述题10分。",
    "score": 9,
    "items": [
     {
      "q": "赏析：《夜起》（黄遵宪）“千声檐铁百淋铃，雨横风狂暂一停。正望鸡鸣天下白，又惊鹅击海东青。沉阴噎噎何多日，残月晖晖尚几星。斗室苍茫吾独立，万家酣睡几人醒？”（重点分析作品的思想内容与艺术特点）",
      "a": "此诗作于1901年辛丑条约签订前夕，原本以为八国联军撤出北京，坐下来谈判，就可获得一刻喘息的机会，但沙俄无理要求攫取东北铁路专营权，通过铁路专营，进一步控制东北，这必将使得满清王朝丢失发祥地。（3分）对此危局，诗人却因放逐家乡，报国无门而忧心如捣，彻夜难眠。反观国人，对此似无警觉，依然是万家酣睡，令人揪心，急需呼吁、警醒国民，起而抗争。因此，满清王朝既丢失祖宗发祥之地，又不能鼓励与激发广大国民爱国之心，应予以批判。（3分）此诗运用了多种艺术手法，如用典故（李贺诗“雄鸡一唱天下白”）、谐音（“鹅”指代俄罗斯）、借喻（用海东青比喻满族）、对偶、反诘等。（3分）",
      "e": ""
     },
     {
      "q": "论述：柳亚子“五四”运动前的诗歌的主要内容是什么？试举例说明。",
      "a": "柳亚子一生诗歌创作数量众多，五四运动以前的诗歌主要包括以下内容：一、政治抒情诗。柳亚子是一个以诗歌为武器的政治诗人。他的诗，紧密结合资产阶级民主革命的发展，洋溢着强烈的爱国主义、民主主义激情，批判封建制度的腐朽没落，揭露人权蹂躏、民气不扬的可悲现实。二、怀友悼亡诗。在广泛的革命交游中，柳亚子写下了大量的怀人诗和赠友诗，表现了对革命胜利的信心和对光明未来的期待。另一些诗或痛心于革命派屡次武装起义的失败，或哀悼死难烈士，反映了现实的残酷和诗人对革命同志的深情。三、反清讨袁诗。柳亚子从年轻时代起就有明确的反清思想，诗歌中往往将咏史和对现实的讽喻结合在一起，通过抒写南宋、明末清初的史事、人物，寄寓诗人对满清统治的批判。辛亥革命后，他的诗转为对这次革命不彻底性的批判。袁世凯演出复辟帝制的丑剧，柳亚子予以痛斥，讨伐这种倒行逆施的行为。（以上3点，每点3分，举例1分）",
      "e": ""
     }
    ]
   }
