      "q": "赏析：《闲眺》（郑珍）“雨过桑麻长，晴光满绿田。人行蚕豆外，蝶度菜花前。台笠家家饷，比邻处处烟。欢声同好语，咸水晒秧田。”",
      "a": "这是一首描写西南地区（遵义）农村风光的五言律诗。全诗以“眺”为线索渐次展开，选取了最具有代表性的景物加以描绘，再现了雨后的自然美景。（3分）此诗以白描手法写成，语言通俗浅显，格调清新明快。（3分）中间两联对仗工整精严，不仅成功地描绘了雨后的景物，而且表达了诗人闲适愉悦的心理感受，回应了题目“闲眺”，风格“工而淡妙”。（3分）",
