      "q": "判断改错：广东兴宁诗人胡晓岑堪称是黄遵宪的同路人，他的《火轮船歌》以新事物入诗，融合时事，笔力奇伟，比黄遵宪的《爱别离》早了16年。",
      "a": "错误（1分）；改为《今别离》（1分）",
      "e": "答案：错误；改为《今别离》。"
